{"id":"call_read_file_051469c077f83a2f","meta":{"emitted_bytes":"2850","estimated_tokens":"713","raw_bytes":"2850"},"name":"read_file","output":"File: main.go (86 lines)\n\n 1 | package main\n 2 | \n 3 | import (\n 4 | \t\"encoding/json\"\n 5 | \t\"errors\"\n 6 | \t\"log\"\n 7 | \t\"net/http\"\n 8 | \t\"time\"\n 9 | )\n10 | \n11 | func main() {\n12 | \tstore := NewStore(30 * time.Minute)\n13 | \thttp.HandleFunc(\"/session\", sessionHandler(store))\n14 | \thttp.HandleFunc(\"/healthz\", healthHandler(store))\n15 | \tlog.Println(\"listening on :8080\")\n16 | \tlog.Fatal(http.ListenAndServe(\":8080\", nil))\n17 | }\n18 | \n19 | // sessionHandler creates a session on POST and reads one on GET.\n20 | func sessionHandler(store *Store) http.HandlerFunc {\n21 | \treturn func(w http.ResponseWriter, r *http.Request) {\n22 | \t\tswitch r.Method {\n23 | \t\tcase http.MethodPost:\n24 | \t\t\tid := r.URL.Query().Get(\"id\")\n25 | \t\t\tuser := r.URL.Query().Get(\"user\")\n26 | \t\t\tif id == \"\" || user == \"\" {\n27 | \t\t\t\thttp.Error(w, \"id and user are required\", http.StatusBadRequest)\n28 | \t\t\t\treturn\n29 | \t\t\t}\n30 | \t\t\tif err := store.Create(id, user); err != nil {\n31 | \t\t\t\thttp.Error(w, err.Error(), mapStoreError(err))\n32 | \t\t\t\treturn\n33 | \t\t\t}\n34 | \t\t\twriteJSON(w, nil)\n35 | \t\tcase http.MethodGet:\n36 | \t\t\tsession, err := store.Get(r.URL.Query().Get(\"id\"))\n37 | \t\t\tif err != nil {\n38 | \t\t\t\thttp.Error(w, err.Error(), mapStoreError(err))\n39 | \t\t\t\treturn\n40 | \t\t\t}\n41 | \t\t\twriteJSON(w, session)\n42 | \t\tdefault:\n43 | \t\t\thttp.Error(w, \"method not allowed\", http.StatusMethodNotAllowed)\n44 | \t\t}\n45 | \t}\n46 | }\n47 | \n48 | type storeErrorStatus struct {\n49 | \terr    error\n50 | \tstatus int\n51 | }\n52 | \n53 | // storeErrorStatuses is the single source of truth for store-error-to-status\n54 | // translation. Its order also makes precedence deterministic for errors that\n55 | // wrap or join more than one