oreErrorStatus{\n57 | \t{err: ErrNotFound, status: http.StatusNotFound},\n58 | \t{err: ErrConflict, status: http.StatusConflict},\n59 | \t{err: ErrInvalidID, status: http.StatusBadRequest},\n60 | \t{err: ErrUserAtCap, status: http.StatusTooManyRequests},\n61 | }\n62 | \n63 | // mapStoreError translates store errors to HTTP response statuses and\n64 | // recognizes wrapped sentinel errors.\n65 | func mapStoreError(err error) int {\n66 | \tfor _, mapping := range storeErrorStatuses {\n67 | \t\tif errors.Is(err, mapping.err) {\n68 | \t\t\treturn mapping.status\n69 | \t\t}\n70 | \t}\n71 | \treturn http.StatusInternalServerError\n72 | }\n73 | \n74 | // writeStoreError gives every HTTP handler a common path for rendering store\n75 | // failures, ensuring that mapStoreError remains the only status translation.\n76 | func writeStoreError(w http.ResponseWriter, err error) {\n77 | \thttp.Error(w, err.Error(), mapStoreError(err))\n78 | }\n79 | \n80 | // healthHandler reports how many sessions are currently held.\n81 | func healthHandler(store *Store) http.HandlerFunc {\n82 | \treturn func(w http.ResponseWriter, r *http.Request) {\n83 | \t\twriteJSON(w, map[string]int{\"sessions\": store.Len()})\n84 | \t}\n85 | }\n86 | \n87 | func writeJSON(w http.ResponseWriter, payload any) {\n88 | \tw.Header().Set(\"Content-Type\", \"application/json\")\n89 | \tif err := json.NewEncoder(w).Encode(payload); err != nil {\n90 | \t\tlog.Printf(\"write response: %v\", err)\n91 | \t}\n92 | }","runId":"run_20260904031447_b3819b","schemaVersion":2,"status":"ok","truncated":false,"type":"tool_result"}
