{"args":{"content":"package main\n\nimport (\n\t\"encoding/json\"\n\t\"errors\"\n\t\"log\"\n\t\"net/http\"\n\t\"time\"\n)\n\nfunc main() {\n\tstore := NewStore(30 * time.Minute)\n\thttp.HandleFunc(\"/session\", sessionHandler(store))\n\thttp.HandleFunc(\"/healthz\", healthHandler(store))\n\tlog.Println(\"listening on :8080\")\n\tlog.Fatal(http.ListenAndServe(\":8080\", nil))\n}\n\n// sessionHandler creates a session on POST and reads one on GET.\nfunc sessionHandler(store *Store) http.HandlerFunc {\n\treturn func(w http.ResponseWriter, r *http.Request) {\n\t\tswitch r.Method {\n\t\tcase http.MethodPost:\n\t\t\tid := r.URL.Query().Get(\"id\")\n\t\t\tuser := r.URL.Query().Get(\"user\")\n\t\t\tif id == \"\" || user == \"\" {\n\t\t\t\thttp.Error(w, \"id and user are required\", http.StatusBadRequest)\n\t\t\t\treturn\n\t\t\t}\n\t\t\tif err := store.Create(id, user); err != nil {\n\t\t\t\twriteStoreError(w, err)\n\t\t\t\treturn\n\t\t\t}\n\t\t\twriteJSON(w, nil)\n\t\tcase http.MethodGet:\n\t\t\tsession, err := store.Get(r.URL.Query().Get(\"id\"))\n\t\t\tif err != nil {\n\t\t\t\twriteStoreError(w, err)\n\t\t\t\treturn\n\t\t\t}\n\t\t\twriteJSON(w, session)\n\t\tdefault:\n\t\t\thttp.Error(w, \"method not allowed\", http.StatusMethodNotAllowed)\n\t\t}\n\t}\n}\n\ntype storeErrorStatus struct {\n\terr    error\n\tstatus int\n}\n\n// storeErrorStatuses is the single source of truth for store-error-to-status\n// translation. Its order also makes precedence deterministic for errors that\n// wrap or join more than one sentinel.\nvar storeErrorStatuses = []storeErrorStatus{\n\t{err: ErrNotFound, status: http.StatusNotFound},\n\t{err: ErrConflict, status: http.StatusConflict},\n\t{err: ErrInvalidID, status: http.StatusBadRequest},\n\t{err: ErrUserAtCap, status: http.StatusTooManyRequests},\n}\n\n// mapStoreError translates store errors to HTTP response statuses and\n// recognizes wrapped sentinel errors.\nfunc mapStoreError(err error) int {\n\tfor _, mapping := range storeErrorStatuses {\n\t\tif errors.Is(err, mapping.err) {\n\t\t\treturn mapping.status\n\t\t}\n\t}\n\treturn http.StatusInternalServerError\n}\n\n// writeStoreError gives every HTTP handler a common path for rendering store\n// failures, ensuring that mapStoreError remains the only status translation.\nfunc writeStoreError(w http.ResponseWriter, err error) {\n\thttp.Error(w, err.Error(), mapStoreError(err))\n}\n\n// healthHandler reports how many sessions are currently held.\nfunc healthHandler(store *Store) http.HandlerFunc {\n\treturn func(w http.ResponseWriter, r *http.Request) {\n\t\twriteJSON(w, map[string]int{\"sessions\": store.Len()})\n\t}\n}\n\nfunc writeJSON(w http.ResponseWriter, payload any) {\n\tw.Header().Set(\"Content-Type\", \"application/json\")\n\tif err := json.NewEncoder(w).Encode(payload); err != nil {\n\t\tlog.Printf(\"write response: %v\", err)\n\t}\n}\n","overwrite":true,"path":"main.go"},"id":"call_write_file_5f2b3b60274a8a8e","name":"write_file","runId":"run_20260904031447_b3819b","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
