verError\n}\n\n// writeStoreError ensures HTTP handlers can report store failures using the\n// same mapping table as sessionHandler.\nfunc writeStoreError(w http.ResponseWriter, err error) {\n\thttp.Error(w, err.Error(), mapStoreError(err))\n}\n\nfunc writeJSON(w http.ResponseWriter, payload any) {\n\tw.Header().Set(\"Content-Type\", \"application/json\")\n\tif err := json.NewEncoder(w).Encode(payload); err != nil {\n\t\tlog.Printf(\"write response: %v\", err)\n\t}\n}\n","overwrite":true,"path":"main.go"},"id":"call_write_file_6ec4595ad4d6e4eb","name":"write_file","runId":"run_20260904032013_1a09f0","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
