{"args":{"content":"package main\n\nimport (\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"testing\"\n\t\"time\"\n)\n\nfunc TestSessionLookupTable(t *testing.T) {\n\tnow := time.Date(2024, time.January, 1, 12, 0, 0, 0, time.UTC)\n\tstore := newSessionStore()\n\tstore.now = func() time.Time { return now }\n\tstore.sessions[\"live\"] = session{expiresAt: now.Add(time.Hour)}\n\n\tmux := http.NewServeMux()\n\tmux.HandleFunc(\"/session\", store.handleSession)\n\n\ttests := []struct {\n\t\tname   string\n\t\tmethod string\n\t\ttarget string\n\t\twant   int\n\t}{\n\t\t{name: \"live\", method: http.MethodGet, target: \"/session?id=live\", want: http.StatusOK},\n\t\t{name: \"missing\", method: http.MethodGet, target: \"/session?id=missing\", want: http.StatusNotFound},\n\t\t{name: \"wrong method\", method: http.MethodPost, target: \"/session?id=live\", want: http.StatusMethodNotAllowed},\n\t}\n\n\tfor _, tt := range tests {\n\t\tt.Run(tt.name, func(t *testing.T) {\n\t\t\trecorder := httptest.NewRecorder()\n\t\t\trequest := httptest.NewRequest(tt.method, tt.target, nil)\n\n\t\t\tmux.ServeHTTP(recorder, request)\n\n\t\t\tif recorder.Code != tt.want {\n\t\t\t\tt.Fatalf(\"%s %s: got status %d, want %d\", tt.method, tt.target, recorder.Code, tt.want)\n\t\t\t}\n\t\t})\n\t}\n}\n","path":"lookup_table_test.go"},"id":"call_write_file_7f7348de4d70420b","name":"write_file","runId":"run_20260904033800_e28fba","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
