{"args":{"content":"package main\n\nimport (\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"testing\"\n\t\"time\"\n)\n\nfunc TestSessionLookupTable(t *testing.T) {\n\tbaseTime := time.Date(2100, time.January, 2, 3, 4, 5, 0, time.UTC)\n\n\ttests := []struct {\n\t\tname       string\n\t\tmethod     string\n\t\ttarget     string\n\t\twantStatus int\n\t}{\n\t\t{\n\t\t\tname:       \"live session\",\n\t\t\tmethod:     http.MethodGet,\n\t\t\ttarget:     \"/session?id=live\",\n\t\t\twantStatus: http.StatusOK,\n\t\t},\n\t\t{\n\t\t\tname:       \"missing session\",\n\t\t\tmethod:     http.MethodGet,\n\t\t\ttarget:     \"/session?id=missing\",\n\t\t\twantStatus: http.StatusNotFound,\n\t\t},\n\t\t{\n\t\t\tname:       \"wrong method\",\n\t\t\tmethod:     http.MethodPost,\n\t\t\ttarget:     \"/session?id=live\",\n\t\t\twantStatus: http.StatusMethodNotAllowed,\n\t\t},\n\t}\n\n\tfor _, tt := range tests {\n\t\ttt := tt\n\t\tt.Run(tt.name, func(t *testing.T) {\n\t\t\tcurrentTime := baseTime\n\t\t\tstore := newSessionStore()\n\t\t\tstore.now = func() time.Time { return currentTime }\n\t\t\tstore.sessions[\"live\"] = session{\n\t\t\t\tid:        \"live\",\n\t\t\t\texpiresAt: currentTime.Add(time.Hour),\n\t\t\t}\n\n\t\t\tmux := http.NewServeMux()\n\t\t\tmux.HandleFunc(\"/session\", store.handleSession)\n\n\t\t\trecorder := httptest.NewRecorder()\n\t\t\trequest := httptest.NewRequest(tt.method, tt.target, nil)\n\t\t\tmux.ServeHTTP(recorder, request)\n\n\t\t\tif recorder.Code != tt.wantStatus {\n\t\t\t\tt.Fatalf(\"status = %d, want %d\", recorder.Code, tt.wantStatus)\n\t\t\t}\n\t\t})\n\t}\n}\n","overwrite":true,"path":"lookup_table_test.go"},"id":"call_write_file_ec5ef0c69c4a6cfa","name":"write_file","runId":"run_20260904034110_eb2304","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
