{"args":{"content":"package main\n\nimport (\n\t\"go/ast\"\n\t\"go/build\"\n\t\"go/parser\"\n\t\"go/token\"\n\t\"strconv\"\n\t\"testing\"\n)\n\nfunc TestSessionBuildConstraintsAreMutuallyExclusive(t *testing.T) {\n\ttests := []struct {\n\t\tname      string\n\t\tbuildTags []string\n\t\twantUnix  bool\n\t\twantOther bool\n\t}{\n\t\t{name: \"without unix tag\", wantUnix: false, wantOther: true},\n\t\t{name: \"with unix tag\", buildTags: []string{\"unix\"}, wantUnix: true, wantOther: false},\n\t}\n\n\tfor _, tt := range tests {\n\t\tt.Run(tt.name, func(t *testing.T) {\n\t\t\tctx := build.Default\n\t\t\tctx.BuildTags = tt.buildTags\n\n\t\t\tunixMatch, err := ctx.MatchFile(\".\", \"session_unix.go\")\n\t\t\tif err != nil {\n\t\t\t\tt.Fatalf(\"matching session_unix.go: %v\", err)\n\t\t\t}\n\t\t\totherMatch, err := ctx.MatchFile(\".\", \"session_other.go\")\n\t\t\tif err != nil {\n\t\t\t\tt.Fatalf(\"matching session_other.go: %v\", err)\n\t\t\t}\n\n\t\t\tif unixMatch != tt.wantUnix {\n\t\t\t\tt.Errorf(\"session_unix.go match = %v, want %v\", unixMatch, tt.wantUnix)\n\t\t\t}\n\t\t\tif otherMatch != tt.wantOther {\n\t\t\t\tt.Errorf(\"session_other.go match = %v, want %v\", otherMatch, tt.wantOther)\n\t\t\t}\n\t\t\tif unixMatch == otherMatch {\n\t\t\t\tt.Errorf(\"implementations must be mutually exclusive; unix match = %v, other match = %v\", unixMatch, otherMatch)\n\t\t\t}\n\t\t})\n\t}\n}\n\nfunc TestSessionPlatformNoteImplementations(t *testing.T) {\n\tassertPlatformNoteImplementation(t, \"session_unix.go\", \"unix\")\n\tassertPlatformNoteImplementation(t, \"session_other.go\", \"other\")\n}\n\nfunc assertPlatformNoteImplementation(t *testing.T, filename, want string) {\n\tt.Helper()\n\n\tfile, err := parser.ParseFile(token.NewFileSet(), filename, nil, 0)\n\tif err != nil {\n\t\tt.Fatalf(\"parsing %s: %v\", filename, err)\n\t}\n\tif file.Name.Name != \"main\" {\n\t\tt.Fatalf(\"%s package = %q, want %q\", filename, file.Name.Name, \"main\")\n\t}\n\n\tvar matches []*ast.FuncDecl\n\tfor _, decl := range file.Decls {\n\t\tif fn, ok := decl.(*ast.FuncDecl); ok \u0026\u0026 fn.Name.Name == \"platformNote\" {\n\t\t\tmatches = append(matches, fn)\n\t\t}\n\t}\n\tif len(matches) != 1 {\n\t\tt.Fatalf(\"%s contains %d platformNote declarations, want exactly 1\", filename, len(matches))\n\t}\n\n\tfn := matches[0]\n\tif fn.Recv != nil || fn.Type.Params.NumFields() != 0 {\n\t\tt.Fatalf(\"%s platformNote must be a receiverless function with no parameters\", filename)\n\t}\n\tif fn.Type.Results == nil || len(fn.Type.Results.List) != 1 {\n\t\tt.Fatalf(\"%s platformNote must have exactly one result\", filename)\n\t}\n\tresultType, ok := fn.Type.Results.List[0].Type.(*ast.Ident)\n\tif !ok || resultType.Name != \"string\" {\n\t\tt.Fatalf(\"%s platformNote result must be string\", filename)\n\t}\n\tif fn.Body == nil || len(fn.Body.List) != 1 {\n\t\tt.Fatalf(\"%s platformNote must contain exactly one return statement\", filename)\n\t}\n\tret, ok := fn.Body.List[0].(*ast.ReturnStmt)\n\tif !ok || len(ret.Results) != 1 {\n\t\tt.Fatalf(\"%s platformNote must return exactly one value\", filename)\n\t}\n\tliteral, ok := ret.Results[0].(*ast.BasicLit)\n\tif !ok || literal.Kind != token.STRING {\n\t\tt.Fatalf(\"%s platformNote must return a string literal\", filename)\n\t}\n\tgot, err := strconv.Unquote(literal.Value)\n\tif err != nil {\n\t\tt.Fatalf(\"unquoting platformNote result in %s: %v\", filename, err)\n\t}\n\tif got != want {\n\t\tt.Errorf(\"%s platformNote returns %q, want %q\", filename, got, want)\n\t}\n}\n","path":"session_build_tag_behavior_test.go"},"id":"call_write_file_a01f26054bf42b53","name":"write_file","runId":"run_20260904035104_28a532","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
